export const DEXTEXT = {"1":{"genus":"Pokémon Semente","text":"Uma semente estranha foi plantada em suas costas ao nascer. A planta brota e cresce junto com este Pokémon."},"2":{"genus":"Pokémon Semente","text":"Quando o bulbo em suas costas fica grande, parece perder a capacidade de ficar de pé sobre as patas traseiras."},"3":{"genus":"Pokémon Semente","text":"A planta floresce quando está absorvendo energia solar. Está sempre em movimento em busca de luz do sol."},"4":{"genus":"Pokémon Lagarto","text":"Obviamente prefere lugares quentes. Dizem que, quando chove, sai vapor da ponta de sua cauda."},"5":{"genus":"Pokémon Chama","text":"Quando balança sua cauda em chamas, eleva a temperatura a níveis insuportavelmente altos."},"6":{"genus":"Pokémon Chama","text":"Cospe um fogo tão quente que é capaz de derreter rochas. É conhecido por causar incêndios florestais sem querer."},"7":{"genus":"Pokémon Tartaruguinha","text":"Depois de nascer, suas costas incham e endurecem, formando um casco. Lança jatos poderosos de espuma pela boca."},"8":{"genus":"Pokémon Tartaruga","text":"Costuma se esconder na água para espreitar presas desatentas. Para nadar rápido, move as orelhas para manter o equilíbrio."},"9":{"genus":"Pokémon Marisco","text":"Um Pokémon brutal com jatos de água pressurizada em seu casco. Eles são usados em investidas em alta velocidade."},"10":{"genus":"Pokémon Verme","text":"Seus pés curtos têm ventosas nas pontas que permitem que ele escale encostas e paredes sem se cansar."},"11":{"genus":"Pokémon Casulo","text":"Este Pokémon fica vulnerável a ataques enquanto sua casca está mole, expondo seu corpo fraco e delicado."},"12":{"genus":"Pokémon Borboleta","text":"Em batalha, bate as asas em alta velocidade para liberar no ar um pó altamente tóxico."},"13":{"genus":"Pokémon Inseto Peludo","text":"É encontrado com frequência nas florestas, comendo folhas. Tem um ferrão afiado e venenoso na cabeça."},"14":{"genus":"Pokémon Casulo","text":"Quase incapaz de se mover, este Pokémon só consegue endurecer sua casca para se proteger dos predadores."},"15":{"genus":"Pokémon Abelha Venenosa","text":"Tem três ferrões venenosos nas patas dianteiras e na cauda. Eles são usados para golpear o inimigo repetidamente."},"16":{"genus":"Pokémon Passarinho","text":"É comum vê-lo em florestas e bosques. Bate as asas rente ao chão para levantar areia e cegar os inimigos."},"17":{"genus":"Pokémon Pássaro","text":"Muito protetor de seu vasto território, este Pokémon bica ferozmente qualquer intruso."},"18":{"genus":"Pokémon Pássaro","text":"Quando caça, voa rente à superfície da água em alta velocidade para apanhar presas desatentas, como Magikarp."},"19":{"genus":"Pokémon Rato","text":"Morde qualquer coisa quando ataca. Pequeno e muito rápido, é comum vê-lo em vários lugares."},"20":{"genus":"Pokémon Rato","text":"Usa seus bigodes para manter o equilíbrio. Aparentemente fica mais lento se eles forem cortados."},"21":{"genus":"Pokémon Passarinho","text":"Bate suas pequenas asas sem parar para voar. Usando o bico, procura presas no meio do mato."},"22":{"genus":"Pokémon Bico","text":"Com suas asas enormes e magníficas, consegue se manter no ar sem nunca precisar pousar para descansar."},"23":{"genus":"Pokémon Cobra","text":"Move-se em silêncio e às escondidas. Engole inteiros os ovos de pássaros como Pidgey e Spearow."},"24":{"genus":"Pokémon Naja","text":"Dizem que as ferozes marcas de alerta em sua barriga variam de região para região."},"25":{"genus":"Pokémon Rato","text":"Quando vários destes Pokémon se reúnem, a eletricidade deles pode se acumular e causar tempestades de raios."},"26":{"genus":"Pokémon Rato","text":"Sua longa cauda funciona como um fio terra que o protege de sua própria energia de alta voltagem."},"27":{"genus":"Pokémon Rato","text":"Cava tocas bem fundo sob a terra em locais áridos, longe da água. Só sai para caçar comida."},"28":{"genus":"Pokémon Rato","text":"Enrola-se como uma bola de espinhos quando se sente ameaçado. Consegue rolar enrolado para atacar ou fugir."},"29":{"genus":"Pokémon Espinho Venenoso","text":"Apesar de pequeno, seus espinhos venenosos tornam este Pokémon perigoso. A fêmea tem chifres menores."},"30":{"genus":"Pokémon Espinho Venenoso","text":"O chifre da fêmea se desenvolve lentamente. Prefere ataques físicos, como arranhões e mordidas."},"31":{"genus":"Pokémon Broca","text":"Suas escamas duras oferecem uma proteção forte. Usa seu corpo robusto para executar golpes poderosos."},"32":{"genus":"Pokémon Espinho Venenoso","text":"Deixa as orelhas eretas para sentir o perigo. Quanto maiores seus chifres, mais poderoso é o veneno que secreta."},"33":{"genus":"Pokémon Espinho Venenoso","text":"Um Pokémon agressivo que ataca sem hesitar. O chifre em sua cabeça secreta um veneno poderoso."},"34":{"genus":"Pokémon Broca","text":"Usa sua cauda poderosa em batalha para esmagar e apertar a presa, até quebrar seus ossos."},"35":{"genus":"Pokémon Fada","text":"Seu charme mágico e fofo tem muitos admiradores. É raro e só é encontrado em certas áreas."},"36":{"genus":"Pokémon Fada","text":"Um Pokémon fada tímido, raramente visto. Foge e se esconde assim que percebe a presença de pessoas."},"37":{"genus":"Pokémon Raposa","text":"Ao nascer, tem apenas uma cauda. A cauda se divide a partir da ponta conforme ele envelhece."},"38":{"genus":"Pokémon Raposa","text":"Muito inteligente e muito vingativo. Agarrar uma de suas várias caudas pode resultar em uma maldição de mil anos."},"39":{"genus":"Pokémon Balão","text":"Quando seus olhos enormes brilham, canta uma melodia misteriosamente suave que faz os inimigos adormecerem."},"40":{"genus":"Pokémon Balão","text":"Seu corpo é macio e borrachudo. Quando fica bravo, suga ar e se infla até atingir um tamanho enorme."},"41":{"genus":"Pokémon Morcego","text":"Forma colônias em lugares eternamente escuros. Usa ondas ultrassônicas para identificar e se aproximar dos alvos."},"42":{"genus":"Pokémon Morcego","text":"Depois que ataca, não para de drenar a energia da vítima, mesmo que fique pesado demais para voar."},"43":{"genus":"Pokémon Erva Daninha","text":"Durante o dia, mantém o rosto enterrado no chão. À noite, perambula espalhando suas sementes."},"44":{"genus":"Pokémon Erva Daninha","text":"O líquido que escorre de sua boca não é baba. É um néctar usado para atrair presas."},"45":{"genus":"Pokémon Flor","text":"Tem as maiores pétalas do mundo. A cada passo, as pétalas soltam densas nuvens de pólen tóxico."},"46":{"genus":"Pokémon Cogumelo","text":"Cava para sugar raízes de árvores. Os cogumelos em suas costas crescem tirando nutrientes do inseto hospedeiro."},"47":{"genus":"Pokémon Cogumelo","text":"Uma dupla de hospedeiro e parasita em que o cogumelo parasita tomou conta do inseto hospedeiro. Prefere lugares úmidos."},"48":{"genus":"Pokémon Inseto","text":"Vive à sombra de árvores altas, onde come insetos. À noite, é atraído pela luz."},"49":{"genus":"Pokémon Mariposa Venenosa","text":"As escamas em forma de pó que cobrem suas asas têm cores que indicam os tipos de veneno que possui."},"50":{"genus":"Pokémon Toupeira","text":"Vive a cerca de um metro abaixo da terra, onde se alimenta de raízes de plantas. Às vezes aparece na superfície."},"51":{"genus":"Pokémon Toupeira","text":"Uma equipe de trigêmeos Diglett. Provoca terremotos enormes ao cavar a quase 100 km de profundidade."},"52":{"genus":"Pokémon Gato Arranhador","text":"Lava o rosto com frequência para manter a moeda em sua testa sempre brilhando. Não se dá bem com o Meowth de Galar."},"53":{"genus":"Pokémon Gato Elegante","text":"Embora sua pelagem tenha muitos admiradores, é difícil criá-lo como bicho de estimação por causa de seu temperamento instável e maldoso."},"54":{"genus":"Pokémon Pato","text":"Enquanto engana os inimigos com seu olhar vazio, este Pokémon astuto usa poderes psicocinéticos."},"55":{"genus":"Pokémon Pato","text":"É visto com frequência nadando elegantemente perto das margens de lagos. Costuma ser confundido com o monstro japonês Kappa."},"56":{"genus":"Pokémon Macaco-Porco","text":"Fica furioso com extrema facilidade. Pode estar dócil em um momento e se debatendo de raiva no instante seguinte."},"57":{"genus":"Pokémon Macaco-Porco","text":"Está sempre furioso e, ainda por cima, é teimoso. Não desiste de perseguir sua presa até alcançá-la."},"58":{"genus":"Pokémon Filhote","text":"Muito protetor de seu território. Late e morde para expulsar intrusos de seu espaço."},"59":{"genus":"Pokémon Lendário","text":"Um Pokémon admirado desde a antiguidade por sua beleza. Corre com tanta agilidade que parece ter asas."},"60":{"genus":"Pokémon Girino","text":"Suas pernas recém-crescidas o impedem de correr. Parece preferir nadar a tentar ficar de pé."},"61":{"genus":"Pokémon Girino","text":"Consegue viver dentro e fora da água. Quando está fora da água, transpira para manter o corpo escorregadio."},"62":{"genus":"Pokémon Girino","text":"Um nadador habilidoso tanto no nado livre quanto no nado de peito. Ultrapassa facilmente os melhores nadadores humanos."},"63":{"genus":"Pokémon Psi","text":"Usando sua habilidade de ler mentes, identifica perigos iminentes e usa Teleporte para se pôr em segurança."},"64":{"genus":"Pokémon Psi","text":"Emite de seu corpo ondas alfa especiais que causam dores de cabeça em quem simplesmente fica por perto."},"65":{"genus":"Pokémon Psi","text":"Seu cérebro tem desempenho superior ao de um supercomputador. Dizem que seu QI é de 5.000."},"66":{"genus":"Pokémon Superpoder","text":"Adora desenvolver os músculos. Treina todos os estilos de artes marciais para ficar ainda mais forte."},"67":{"genus":"Pokémon Superpoder","text":"Seu corpo musculoso é tão poderoso que precisa usar um cinto limitador de força para conseguir controlar seus movimentos."},"68":{"genus":"Pokémon Superpoder","text":"Usando seus músculos pesados, desfere socos poderosos capazes de mandar a vítima para além do horizonte."},"69":{"genus":"Pokémon Flor","text":"Um Pokémon carnívoro que captura e come insetos. Usa seus pés em forma de raiz para absorver a umidade de que precisa."},"70":{"genus":"Pokémon Papa-Moscas","text":"Cospe Pó Venenoso para imobilizar o inimigo e depois o finaliza com um jato de Ácido."},"71":{"genus":"Pokémon Papa-Moscas","text":"Dizem que vive em enormes colônias nas profundezas das selvas, mas ninguém jamais voltou de lá."},"72":{"genus":"Pokémon Água-Viva","text":"Fica à deriva em mares rasos. Pescadores que o fisgam por acidente costumam ser punidos com seu ácido urticante."},"73":{"genus":"Pokémon Água-Viva","text":"Os tentáculos normalmente ficam curtos. Durante a caça, eles se estendem para enredar e imobilizar a presa."},"74":{"genus":"Pokémon Rocha","text":"Encontrado em campos e montanhas. Confundindo-os com pedras, as pessoas costumam pisar ou tropeçar neles."},"75":{"genus":"Pokémon Rocha","text":"Desce as encostas rolando para se locomover. Passa por cima de qualquer obstáculo sem diminuir a velocidade nem mudar de direção."},"76":{"genus":"Pokémon Megaton","text":"Seu corpo, que parece uma rocha, é extremamente duro. Aguenta facilmente explosões de dinamite sem sofrer danos."},"77":{"genus":"Pokémon Cavalo de Fogo","text":"Seus cascos são 10 vezes mais duros que diamantes. Consegue pisotear qualquer coisa até deixá-la completamente achatada em pouco tempo."},"78":{"genus":"Pokémon Cavalo de Fogo","text":"Muito competitivo, este Pokémon persegue qualquer coisa que se mova rápido na esperança de apostar uma corrida."},"79":{"genus":"Pokémon Lerdo","text":"Incrivelmente lento e lerdo. Leva 5 segundos para sentir dor quando é atacado."},"80":{"genus":"Pokémon Caranguejo-Ermitão","text":"Dizem que o Shellder grudado na cauda de Slowpoke se alimenta dos restos de comida do hospedeiro."},"81":{"genus":"Pokémon Ímã","text":"Usa antigravidade para ficar suspenso no ar. Aparece sem aviso e usa Onda Trovão e golpes parecidos."},"82":{"genus":"Pokémon Ímã","text":"Formado por vários Magnemite ligados entre si. Costumam aparecer com frequência quando há erupções de manchas solares."},"83":{"genus":"Pokémon Pato Selvagem","text":"O talo de cebolinha que segura é sua arma. Ele é usado de forma muito parecida com uma espada de metal."},"84":{"genus":"Pokémon Pássaro Duplo","text":"Uma ave que compensa o voo fraco com a velocidade de suas pernas. Deixa pegadas gigantes."},"85":{"genus":"Pokémon Pássaro Triplo","text":"Usa seus três cérebros para executar planos complexos. Enquanto duas cabeças dormem, uma fica acordada."},"86":{"genus":"Pokémon Leão-Marinho","text":"O chifre saliente em sua cabeça é muito duro. Ele é usado para abrir caminho através de gelo espesso."},"87":{"genus":"Pokémon Leão-Marinho","text":"Armazena energia térmica no corpo. Nada a constantes 8 nós, mesmo em águas extremamente frias."},"88":{"genus":"Pokémon Lodo","text":"Aparece em áreas imundas. Prospera sugando o lodo poluído que é despejado pelas fábricas."},"89":{"genus":"Pokémon Lodo","text":"Coberto por uma espessa camada de lodo imundo e nojento. É tão tóxico que até suas pegadas contêm veneno."},"90":{"genus":"Pokémon Bivalve","text":"Sua concha dura repele qualquer tipo de ataque. Só fica vulnerável quando sua concha está aberta."},"91":{"genus":"Pokémon Bivalve","text":"Quando é atacado, dispara seus chifres em rajadas rápidas. Seu interior nunca foi visto."},"92":{"genus":"Pokémon Gás","text":"Quase invisível, este Pokémon gasoso envolve o alvo e o faz dormir sem que ele perceba."},"93":{"genus":"Pokémon Gás","text":"Por causa de sua habilidade de atravessar paredes, dizem que ele vem de outra dimensão."},"94":{"genus":"Pokémon Sombra","text":"Em noites de lua cheia, este Pokémon gosta de imitar a sombra das pessoas e rir do susto delas."},"95":{"genus":"Pokémon Cobra de Pedra","text":"Conforme cresce, as partes de pedra de seu corpo endurecem até ficarem parecidas com um diamante, só que de cor preta."},"96":{"genus":"Pokémon Hipnose","text":"Faz os inimigos dormirem e depois come seus sonhos. Às vezes passa mal por comer pesadelos."},"97":{"genus":"Pokémon Hipnose","text":"Quando encara um inimigo, usa uma combinação de golpes psíquicos como Hipnose e Confusão."},"98":{"genus":"Pokémon Caranguejo de Rio","text":"Suas pinças não são apenas armas poderosas; também são usadas para manter o equilíbrio ao andar de lado."},"99":{"genus":"Pokémon Pinça","text":"A pinça grande tem 10.000 cavalos de potência de força esmagadora. Porém, seu tamanho enorme a torna difícil de manejar."},"100":{"genus":"Pokémon Bola","text":"Normalmente encontrado em usinas de energia. Por ser facilmente confundido com uma Poké Bola, já deu choque em muita gente."},"101":{"genus":"Pokémon Bola","text":"Armazena energia elétrica sob altíssima pressão. Costuma explodir com pouca ou nenhuma provocação."},"102":{"genus":"Pokémon Ovo","text":"Costuma ser confundido com ovos. Quando são perturbados, se juntam rapidamente e atacam em enxame."},"103":{"genus":"Pokémon Coco","text":"Diz a lenda que, em raras ocasiões, uma de suas cabeças cai e continua vivendo como um Exeggcute."},"104":{"genus":"Pokémon Solitário","text":"Como nunca tira seu capacete de crânio, ninguém jamais viu o verdadeiro rosto deste Pokémon."},"105":{"genus":"Pokémon Guardião de Ossos","text":"O osso que carrega é sua principal arma. Ele o arremessa com habilidade, como um bumerangue, para nocautear os alvos."},"106":{"genus":"Pokémon Chute","text":"Quando está com pressa, suas pernas se alongam progressivamente. Corre com suavidade, dando passadas longas e largas."},"107":{"genus":"Pokémon Soco","text":"Mesmo parecendo não fazer nada, dispara sequências de socos rápidos como um raio, impossíveis de ver."},"108":{"genus":"Pokémon Lambida","text":"Sua língua pode se esticar como a de um camaleão. Deixa uma sensação de formigamento quando lambe os inimigos."},"109":{"genus":"Pokémon Gás Venenoso","text":"Como armazena vários tipos de gases tóxicos no corpo, tende a explodir sem aviso."},"110":{"genus":"Pokémon Gás Venenoso","text":"Onde dois tipos de gases venenosos se encontram, 2 Koffing podem se fundir em um Weezing ao longo de muitos anos."},"111":{"genus":"Pokémon Espinhos","text":"Um Pokémon com uma ideia fixa na cabeça. Depois que começa uma investida, não para de correr até cair no sono."},"112":{"genus":"Pokémon Broca","text":"Protegido por um couro que parece uma armadura, é capaz de viver em lava derretida a 3.600 graus."},"113":{"genus":"Pokémon Ovo","text":"Um Pokémon raro e difícil de encontrar, que dizem trazer felicidade a quem consegue capturá-lo."},"114":{"genus":"Pokémon Vinha","text":"Todo o seu corpo é envolto em vinhas largas, parecidas com algas marinhas. Suas vinhas balançam quando ele anda."},"115":{"genus":"Pokémon Mãe","text":"O filhote raramente se aventura para fora da bolsa protetora da mãe antes de completar 3 anos."},"116":{"genus":"Pokémon Dragão","text":"É conhecido por abater insetos voadores com jatos precisos de tinta disparados da superfície da água."},"117":{"genus":"Pokémon Dragão","text":"Consegue nadar de ré batendo rapidamente suas nadadeiras peitorais, que parecem asas, e sua cauda robusta."},"118":{"genus":"Pokémon Peixe-Dourado","text":"Sua nadadeira caudal ondula como um elegante vestido de baile, o que lhe rendeu o apelido de Rainha das Águas."},"119":{"genus":"Pokémon Peixe-Dourado","text":"Na época de desova do outono, podem ser vistos nadando com força rio acima e por riachos."},"120":{"genus":"Pokémon Forma de Estrela","text":"Se seu corpo for despedaçado, ele pode se regenerar desde que o núcleo vermelho permaneça intacto. O núcleo pisca à meia-noite."},"121":{"genus":"Pokémon Misterioso","text":"Seu núcleo central brilha com as sete cores do arco-íris. Algumas pessoas valorizam o núcleo como uma pedra preciosa."},"122":{"genus":"Pokémon Barreira","text":"Se for interrompido enquanto faz mímica, dá tapas no responsável com suas mãos largas."},"123":{"genus":"Pokémon Louva-a-Deus","text":"Com agilidade e velocidade de ninja, consegue criar a ilusão de que existe mais de um."},"124":{"genus":"Pokémon Forma Humana","text":"Rebola os quadris de forma sedutora enquanto anda. Consegue fazer as pessoas dançarem em sincronia com ele."},"125":{"genus":"Pokémon Elétrico","text":"Normalmente encontrados perto de usinas de energia, podem se afastar e causar grandes apagões nas cidades."},"126":{"genus":"Pokémon Cospe-Fogo","text":"Seu corpo sempre arde com um brilho alaranjado que permite que se esconda perfeitamente entre as chamas."},"127":{"genus":"Pokémon Besouro-Veado","text":"Se não consegue esmagar a vítima com suas pinças, ele a gira no ar e a arremessa com força."},"128":{"genus":"Pokémon Touro Selvagem","text":"Quando mira um inimigo, investe furiosamente enquanto chicoteia o próprio corpo com suas caudas longas."},"129":{"genus":"Pokémon Peixe","text":"Em um passado distante, era um pouco mais forte do que os descendentes terrivelmente fracos que existem hoje."},"130":{"genus":"Pokémon Atroz","text":"Depois que começa a se enfurecer, um Gyarados queima tudo, mesmo no meio de uma forte tempestade."},"131":{"genus":"Pokémon Transporte","text":"Um Pokémon que foi caçado em excesso até quase ser extinto. Consegue levar pessoas através da água."},"132":{"genus":"Pokémon Transformação","text":"Capaz de copiar o código genético de um inimigo para se transformar instantaneamente em uma cópia dele."},"133":{"genus":"Pokémon Evolução","text":"Seu código genético é irregular. Pode sofrer mutação se for exposto à radiação das pedras elementais."},"134":{"genus":"Pokémon Jato de Bolhas","text":"Vive perto da água. Sua longa cauda tem uma nadadeira que muitas vezes é confundida com a de uma sereia."},"135":{"genus":"Pokémon Relâmpago","text":"Acumula íons negativos da atmosfera para disparar raios de 10.000 volts."},"136":{"genus":"Pokémon Chama","text":"Quando armazena energia térmica no corpo, sua temperatura pode subir a mais de 1.600 graus."},"137":{"genus":"Pokémon Virtual","text":"Um Pokémon formado inteiramente por código de programação. Capaz de se mover livremente pelo ciberespaço."},"138":{"genus":"Pokémon Espiral","text":"Embora esteja extinto há muito tempo, em casos raros pode ser ressuscitado geneticamente a partir de fósseis."},"139":{"genus":"Pokémon Espiral","text":"Um Pokémon pré-histórico que foi extinto quando sua concha pesada o impediu de capturar presas."},"140":{"genus":"Pokémon Marisco","text":"Um Pokémon que foi ressuscitado a partir de um fóssil encontrado no que, há eras, era o fundo do oceano."},"141":{"genus":"Pokémon Marisco","text":"Seu formato aerodinâmico é perfeito para nadar. Corta as presas com suas garras e drena seus fluidos corporais."},"142":{"genus":"Pokémon Fóssil","text":"Um Pokémon que dominava os céus na era dos dinossauros. Seus dentes são como lâminas de serra."},"143":{"genus":"Pokémon Dorminhoco","text":"Muito preguiçoso. Só come e dorme. Conforme seu corpanzil redondo cresce, fica cada vez mais preguiçoso."},"144":{"genus":"Pokémon Congelante","text":"Um Pokémon pássaro lendário que dizem aparecer para pessoas condenadas, perdidas em montanhas geladas."},"145":{"genus":"Pokémon Elétrico","text":"Um Pokémon pássaro lendário que dizem surgir das nuvens lançando raios enormes."},"146":{"genus":"Pokémon Chama","text":"Conhecido como o pássaro lendário do fogo. Cada batida de suas asas cria um clarão deslumbrante de chamas."},"147":{"genus":"Pokémon Dragão","text":"Foi considerado por muito tempo um Pokémon mítico, até que recentemente uma pequena colônia foi encontrada vivendo debaixo d'água."},"148":{"genus":"Pokémon Dragão","text":"Um Pokémon místico que exala uma aura suave. Tem a habilidade de mudar as condições do clima."},"149":{"genus":"Pokémon Dragão","text":"Um Pokémon marinho visto raríssimas vezes. Dizem que sua inteligência se iguala à dos humanos."},"150":{"genus":"Pokémon Genético","text":"Foi criado por um cientista após anos de experimentos terríveis de manipulação genética e engenharia de DNA."},"151":{"genus":"Pokémon Nova Espécie","text":"É tão raro que muitos especialistas ainda dizem que ele é uma miragem. Pouquíssimas pessoas no mundo inteiro já o viram."},"152":{"genus":"Pokémon Folha","text":"Um aroma doce exala suavemente da folha em sua cabeça. É dócil e adora tomar banho de sol."},"153":{"genus":"Pokémon Folha","text":"Um cheiro de especiarias vem de ao redor de seu pescoço. Por algum motivo, sentir esse cheiro dá vontade de lutar."},"154":{"genus":"Pokémon Erva","text":"O aroma que sobe de suas pétalas contém uma substância que acalma sentimentos agressivos."},"155":{"genus":"Pokémon Rato de Fogo","text":"Tem uma natureza tímida. Se leva um susto, as chamas em suas costas ardem com mais intensidade."},"156":{"genus":"Pokémon Vulcão","text":"Tome cuidado se ele virar as costas durante uma batalha. Isso significa que vai atacar com o fogo de suas costas."},"157":{"genus":"Pokémon Vulcão","text":"Quando sua fúria chega ao auge, fica tão quente que qualquer coisa que o toque pega fogo instantaneamente."},"158":{"genus":"Pokémon Mandíbula Grande","text":"Suas mandíbulas bem desenvolvidas são poderosas e capazes de esmagar qualquer coisa. Até seu treinador precisa tomar cuidado."},"159":{"genus":"Pokémon Mandíbula Grande","text":"Se perde uma presa, outra nasce no lugar. Sempre há 48 presas enfileiradas em sua boca."},"160":{"genus":"Pokémon Mandíbula Grande","text":"Quando morde com suas mandíbulas enormes e poderosas, sacode a cabeça e dilacera a vítima de forma selvagem."},"161":{"genus":"Pokémon Batedor","text":"Um Pokémon muito cauteloso, que se ergue apoiado na cauda para ter uma visão melhor dos arredores."},"162":{"genus":"Pokémon Corpo Longo","text":"Faz um ninho sob medida para seu corpo longo e magro. É impossível para outros Pokémon entrarem no ninho."},"163":{"genus":"Pokémon Coruja","text":"Está sempre apoiado em um pé só. Troca de pé tão rápido que o movimento raramente pode ser visto."},"164":{"genus":"Pokémon Coruja","text":"Seus olhos são especialmente adaptados. Eles concentram até a luz mais fraca e permitem que enxergue no escuro."},"165":{"genus":"Pokémon Cinco Estrelas","text":"É muito tímido. Fica com medo de se mover quando está sozinho, mas é ativo quando está em grupo."},"166":{"genus":"Pokémon Cinco Estrelas","text":"Quando as estrelas cintilam no céu noturno, ele voa por aí espalhando um pó brilhante."},"167":{"genus":"Pokémon Cospe-Fio","text":"Fica imóvel na mesma posição por dias em sua teia, esperando que uma presa desavisada se aproxime."},"168":{"genus":"Pokémon Pernas Longas","text":"Solta fios não só pela parte traseira, mas também pela boca. É difícil dizer qual lado é qual."},"169":{"genus":"Pokémon Morcego","text":"Voa pela escuridão com suas quatro asas em tanto silêncio que pode passar despercebido mesmo quando está por perto."},"170":{"genus":"Pokémon Peixe-Pescador","text":"Os Chinchou piscam suas antenas brilhantes uns para os outros para demarcar seus respectivos territórios."},"171":{"genus":"Pokémon Luz","text":"A luz que emite é tão forte que consegue iluminar a superfície do mar a partir de quase 5 km de profundidade."},"172":{"genus":"Pokémon Ratinho","text":"Ainda não tem habilidade para armazenar eletricidade. Pode soltar um choque quando se diverte ou se assusta."},"173":{"genus":"Pokémon Forma de Estrela","text":"Por causa de sua silhueta incomum, em forma de estrela, as pessoas acreditam que ele chegou aqui em um meteoro."},"174":{"genus":"Pokémon Balão","text":"Tem um corpo muito macio. Se começa a rolar, sai quicando para todos os lados e fica impossível de parar."},"175":{"genus":"Pokémon Bola de Espinhos","text":"Sua casca parece estar cheia de alegria. Dizem que ele compartilha boa sorte quando é tratado com carinho."},"176":{"genus":"Pokémon Felicidade","text":"Dizem que ele aparece diante de pessoas bondosas e atenciosas e as cobre de felicidade."},"177":{"genus":"Pokémon Passarinho","text":"Como suas asas ainda não estão totalmente desenvolvidas, precisa saltitar para se locomover. Está sempre encarando alguma coisa."},"178":{"genus":"Pokémon Místico","text":"Dizem que ele fica imóvel e quieto porque está vendo o passado e o futuro ao mesmo tempo."},"179":{"genus":"Pokémon Lã","text":"Se eletricidade estática se acumula em seu corpo, sua lã dobra de volume. Tocá-lo dá choque."},"180":{"genus":"Pokémon Lã","text":"Como resultado de armazenar eletricidade demais, desenvolveu partes onde nem mesmo a lã mais fina consegue crescer."},"181":{"genus":"Pokémon Luz","text":"A ponta de sua cauda brilha intensamente e pode ser vista de muito longe. Funciona como um farol para pessoas perdidas."},"182":{"genus":"Pokémon Flor","text":"Abundante nos trópicos. Quando dança, suas pétalas se esfregam e produzem um som agradável, como o de sinos."},"183":{"genus":"Pokémon Rato Aquático","text":"A ponta de sua cauda, que contém um óleo mais leve que a água, permite que ele nade sem se afogar."},"184":{"genus":"Pokémon Coelho Aquático","text":"Vive na água praticamente o dia inteiro. A cor e o padrão de seu corpo funcionam como camuflagem, o que dificulta que os inimigos o vejam na água."},"185":{"genus":"Pokémon Imitação","text":"Embora sempre finja ser uma árvore, sua composição parece ser mais próxima de uma rocha do que de uma planta."},"186":{"genus":"Pokémon Sapo","text":"Se Poliwag e Poliwhirl ouvem seu grito ecoante, eles respondem se reunindo de todos os cantos."},"187":{"genus":"Pokémon Algodão","text":"Para não serem levados pelo vento, se reúnem em grupos. Mas eles adoram uma brisa suave."},"188":{"genus":"Pokémon Algodão","text":"A flor no topo de sua cabeça abre e fecha conforme a temperatura sobe e desce."},"189":{"genus":"Pokémon Algodão","text":"Depois que pega o vento, controla com habilidade seus esporos de algodão para flutuar, podendo até dar a volta ao mundo."},"190":{"genus":"Pokémon Cauda Longa","text":"Sua cauda é tão forte que consegue usá-la para agarrar um galho de árvore e se manter suspenso no ar."},"191":{"genus":"Pokémon Semente","text":"Pode cair do céu de repente. Se for atacado por um Spearow, sacode suas folhas violentamente."},"192":{"genus":"Pokémon Sol","text":"Converte a luz do sol em energia. Na escuridão depois do pôr do sol, fecha suas pétalas e fica imóvel."},"193":{"genus":"Pokémon Asa Transparente","text":"Se bate as asas muito rápido, consegue gerar ondas de choque que estilhaçam as janelas da região."},"194":{"genus":"Pokémon Peixe d'Água","text":"Este Pokémon vive em águas frias. Sai da água para procurar comida quando faz frio lá fora."},"195":{"genus":"Pokémon Peixe d'Água","text":"Este Pokémon despreocupado tem uma natureza tranquila. Quando nada, vive esbarrando nos cascos dos barcos."},"196":{"genus":"Pokémon Sol","text":"Usa os pelos finos que cobrem seu corpo para sentir as correntes de ar e prever as ações do inimigo."},"197":{"genus":"Pokémon Luar","text":"Quando está agitado, este Pokémon se protege borrifando um suor venenoso pelos poros."},"198":{"genus":"Pokémon Escuridão","text":"Temido e odiado por muitos, acredita-se que traz azar a todos que o veem à noite."},"199":{"genus":"Pokémon Real","text":"Tem um intelecto e uma intuição incríveis. Seja qual for a situação, permanece calmo e sereno."},"200":{"genus":"Pokémon Guincho","text":"Gosta de pregar peças, como gritar e uivar para assustar as pessoas à noite."},"201":{"genus":"Pokémon Símbolo","text":"Suas formas parecem hieróglifos de tábuas antigas. Dizem que os dois estão, de algum modo, relacionados."},"202":{"genus":"Pokémon Paciente","text":"Detesta luz e choques. Se for atacado, infla o corpo para fortalecer seu contra-ataque."},"203":{"genus":"Pokémon Pescoço Longo","text":"Sua cauda tem um pequeno cérebro próprio. Cuidado! Se você chegar perto, ela pode reagir ao seu cheiro e morder."},"204":{"genus":"Pokémon Bicho-do-Cesto","text":"Gosta de deixar sua casca mais grossa adicionando camadas de casca de árvore. O peso extra não o incomoda."},"205":{"genus":"Pokémon Bicho-do-Cesto","text":"Todo o seu corpo é protegido por uma casca dura como aço. O que se esconde dentro dessa armadura é um completo mistério."},"206":{"genus":"Pokémon Cobra Terrestre","text":"Quando é avistado, este Pokémon foge de ré, cavando o chão furiosamente com a cauda."},"207":{"genus":"Pokémon Escorpião Voador","text":"Voa direto para o rosto do alvo e então se agarra à vítima assustada para injetar veneno."},"208":{"genus":"Pokémon Cobra de Ferro","text":"Acredita-se que seu corpo se transformou por causa do ferro que se acumulou internamente de tanto engolir terra."},"209":{"genus":"Pokémon Fada","text":"Embora pareça assustador, na verdade é gentil e carinhoso. É muito popular entre as mulheres."},"210":{"genus":"Pokémon Fada","text":"Na verdade é tímido e se assusta com facilidade. Se for atacado, se debate para afastar o agressor."},"211":{"genus":"Pokémon Balão","text":"Para disparar seus espinhos venenosos, precisa inflar o corpo bebendo quase 10 litros de água de uma só vez."},"212":{"genus":"Pokémon Pinça","text":"Tem um corpo duro como aço. Intimida os inimigos erguendo suas pinças com padrões que parecem olhos."},"213":{"genus":"Pokémon Mofo","text":"As frutas silvestres que armazena em sua casca em forma de vaso se decompõem e viram um líquido pegajoso."},"214":{"genus":"Pokémon Chifre Único","text":"Normalmente é dócil, mas se for incomodado enquanto bebe néctar, expulsa o intruso com seu chifre."},"215":{"genus":"Pokémon Garra Afiada","text":"Suas patas escondem garras afiadas. Se for atacado, estende as garras de repente e assusta o inimigo."},"216":{"genus":"Pokémon Ursinho","text":"Se encontra mel, sua marca de lua crescente brilha. Está sempre lambendo as patas, porque elas vivem lambuzadas de mel."},"217":{"genus":"Pokémon Hibernante","text":"Embora seja bom em escalar, prefere quebrar árvores com as patas dianteiras e comer as frutas silvestres que caem."},"218":{"genus":"Pokémon Lava","text":"Nunca dorme. Precisa continuar se movendo, porque, se parasse, seu corpo de magma esfriaria e endureceria."},"219":{"genus":"Pokémon Lava","text":"A concha em suas costas é apenas pele que esfriou e endureceu. Ela se quebra facilmente com um leve toque."},"220":{"genus":"Pokémon Porco","text":"Esfrega o focinho no chão para encontrar e desenterrar comida. Às vezes descobre fontes termais."},"221":{"genus":"Pokémon Suíno","text":"Como os pelos longos que cobrem todo o seu corpo atrapalham sua visão, ele simplesmente continua investindo sem parar."},"222":{"genus":"Pokémon Coral","text":"Está sempre perdendo partes e crescendo de novo. A ponta de sua cabeça é valorizada como um tesouro por sua beleza."},"223":{"genus":"Pokémon Jato","text":"Tem uma pontaria excelente. A água que dispara consegue acertar até presas em movimento a mais de 90 metros de distância."},"224":{"genus":"Pokémon Jato","text":"Prende os inimigos com seus tentáculos cheios de ventosas e então os esmaga com sua cabeça dura como pedra."},"225":{"genus":"Pokémon Entrega","text":"Carrega comida o dia inteiro. Há histórias de pessoas perdidas que foram salvas pela comida que ele levava."},"226":{"genus":"Pokémon Pipa","text":"Enquanto nada majestosamente, não se importa se Remoraid se prendem a ele para aproveitar suas sobras."},"227":{"genus":"Pokémon Pássaro Blindado","text":"Suas asas resistentes parecem pesadas, mas na verdade são ocas e leves, o que permite que voe livremente pelo céu."},"228":{"genus":"Pokémon Sombrio","text":"Usa diferentes tipos de latidos para se comunicar com outros de sua espécie e para perseguir suas presas."},"229":{"genus":"Pokémon Sombrio","text":"Se você for queimado pelas chamas que ele dispara pela boca, a dor nunca vai passar."},"230":{"genus":"Pokémon Dragão","text":"Dizem que costuma se esconder em cavernas submarinas. Consegue criar redemoinhos só de bocejar."},"231":{"genus":"Pokémon Nariz Longo","text":"Balança sua longa tromba de forma brincalhona, mas, como é muito forte, isso pode ser perigoso."},"232":{"genus":"Pokémon Armadura","text":"Tem presas afiadas e duras e um couro áspero. Seu Investida é forte o bastante para derrubar uma casa."},"233":{"genus":"Pokémon Virtual","text":"Esta versão aprimorada de Porygon foi projetada para a exploração espacial. Mas ele não consegue voar."},"234":{"genus":"Pokémon Chifre Grande","text":"Seus chifres curvos alteram sutilmente o fluxo de ar, criando um espaço estranho onde a realidade fica distorcida."},"235":{"genus":"Pokémon Pintor","text":"Um fluido especial escorre da ponta de sua cauda. Ele pinta esse fluido por toda parte para marcar seu território."},"236":{"genus":"Pokémon Briga","text":"Está sempre transbordando de energia. Para ficar mais forte, continua lutando mesmo quando perde."},"237":{"genus":"Pokémon Parada de Mão","text":"Se você ficar encantado com seus chutes suaves e elegantes, que parecem uma dança, pode acabar levando um golpe em cheio."},"238":{"genus":"Pokémon Beijo","text":"Seus lábios são a parte mais sensível de seu corpo. Sempre usa os lábios primeiro para examinar as coisas."},"239":{"genus":"Pokémon Elétrico","text":"Gira os braços para gerar eletricidade, mas se cansa facilmente, então só consegue acumular um pouquinho de carga."},"240":{"genus":"Pokémon Brasa Viva","text":"Toda vez que inspira e expira, brasas quentes escorrem de sua boca e de suas narinas."},"241":{"genus":"Pokémon Vaca Leiteira","text":"Seu leite é cheio de nutrientes, o que o torna a bebida perfeita para quem está doente ou cansado."},"242":{"genus":"Pokémon Felicidade","text":"Qualquer um que dê uma única mordida no ovo de Blissey se torna, sem exceção, atencioso e gentil com todos."},"243":{"genus":"Pokémon Trovão","text":"As nuvens de chuva que carrega permitem que dispare raios à vontade. Dizem que ele desceu junto com um relâmpago."},"244":{"genus":"Pokémon Vulcão","text":"Vulcões entram em erupção quando ele late. Incapaz de conter seu poder extremo, corre desenfreado pelas terras."},"245":{"genus":"Pokémon Aurora","text":"Corre pelo mundo para purificar águas poluídas. Parte em disparada junto com o vento norte."},"246":{"genus":"Pokémon Pele de Rocha","text":"Alimenta-se de terra. Depois de comer uma montanha inteira, adormece para poder crescer."},"247":{"genus":"Pokémon Casca Dura","text":"Sua casca é dura como rocha e também muito resistente. Seu Surra consegue derrubar uma montanha."},"248":{"genus":"Pokémon Armadura","text":"Seu corpo não pode ser ferido por nenhum tipo de ataque, por isso está sempre ansioso para desafiar inimigos."},"249":{"genus":"Pokémon Mergulho","text":"Dizem que ele passa o tempo em silêncio nas profundezas do mar porque seus poderes são fortes demais."},"250":{"genus":"Pokémon Arco-Íris","text":"Lendas afirmam que este Pokémon voa sem parar pelos céus do mundo com suas magníficas asas de sete cores."},"251":{"genus":"Pokémon Viagem no Tempo","text":"Este Pokémon vaga através do tempo. A grama e as árvores florescem nas florestas onde ele aparece."},"252":{"genus":"Pokémon Lagartixa da Floresta","text":"Treecko tem pequenos ganchos na sola dos pés que permitem que escale paredes verticais. Este Pokémon ataca golpeando os inimigos com sua cauda grossa."},"253":{"genus":"Pokémon Lagartixa da Floresta","text":"As folhas que crescem no corpo de Grovyle são úteis para camuflá-lo dos inimigos na floresta. Este Pokémon é um mestre em escalar árvores nas selvas."},"254":{"genus":"Pokémon Floresta","text":"As folhas que crescem no corpo de Sceptile têm bordas muito afiadas. Este Pokémon é muito ágil: salta por todos os galhos das árvores e cai sobre o inimigo por cima ou por trás."},"255":{"genus":"Pokémon Pintinho","text":"Torchic gruda em seu Treinador, seguindo-o com passos vacilantes. Este Pokémon cospe fogo a mais de 980 °C, incluindo bolas de fogo que deixam o inimigo carbonizado."},"256":{"genus":"Pokémon Frango Jovem","text":"Combusken fortalece as pernas e as coxas correndo por campos e montanhas. As pernas deste Pokémon têm velocidade e força, o que permite que desfira dez chutes em um segundo."},"257":{"genus":"Pokémon Labareda","text":"Em batalha, Blaziken solta chamas intensas pelos pulsos e ataca os inimigos com coragem. Quanto mais forte o inimigo, mais intensamente queimam os pulsos deste Pokémon."},"258":{"genus":"Pokémon Peixe da Lama","text":"A barbatana na cabeça de Mudkip funciona como um radar altamente sensível. Usando essa barbatana para sentir os movimentos da água e do ar, este Pokémon consegue saber o que acontece ao seu redor sem usar os olhos."},"259":{"genus":"Pokémon Peixe da Lama","text":"A superfície do corpo de Marshtomp é envolvida por uma película fina e pegajosa que permite que ele viva em terra. Este Pokémon brinca na lama das praias quando a maré está baixa."},"260":{"genus":"Pokémon Peixe da Lama","text":"Swampert é muito forte. Tem força suficiente para arrastar com facilidade uma rocha de mais de uma tonelada. Este Pokémon também tem uma visão poderosa, que permite enxergar até em águas turvas."},"261":{"genus":"Pokémon Mordida","text":"Logo de cara, Poochyena tenta morder qualquer coisa que se mova. Este Pokémon persegue a presa até ela ficar exausta. Porém, pode dar meia-volta e fugir se a presa revidar."},"262":{"genus":"Pokémon Mordida","text":"Mightyena dá sinais claros quando está se preparando para atacar. Começa a rosnar grave e depois abaixa o corpo. Este Pokémon morde com selvageria usando suas presas pontiagudas."},"263":{"genus":"Pokémon Guaxinim Pequeno","text":"Zigzagoon vaga inquieto por toda parte, o tempo todo. Este Pokémon faz isso porque é muito curioso. Ele se interessa por qualquer coisa que veja pela frente."},"264":{"genus":"Pokémon Apressado","text":"Linoone sempre corre a toda velocidade e somente em linha reta. Se encontra um obstáculo, faz uma curva em ângulo reto para desviar. Este Pokémon tem muita dificuldade com estradas de curvas suaves."},"265":{"genus":"Pokémon Verme","text":"Usando os espinhos na parte traseira, Wurmple arranca a casca das árvores e se alimenta da seiva que escorre. Os pés deste Pokémon têm ventosas nas pontas que permitem que ele se prenda ao vidro sem escorregar."},"266":{"genus":"Pokémon Casulo","text":"Silcoon se prende a um galho de árvore usando seda para não cair. Ali, este Pokémon fica pendurado em silêncio enquanto aguarda a evolução. Ele espia para fora do casulo de seda por um pequeno buraco."},"267":{"genus":"Pokémon Borboleta","text":"A comida favorita de Beautifly é o pólen doce das flores. Se quiser ver este Pokémon, basta deixar um vaso de flores perto de uma janela aberta. Beautifly com certeza virá procurar pólen."},"268":{"genus":"Pokémon Casulo","text":"Cascoon faz seu casulo protetor envolvendo todo o corpo com uma seda fina que sai de sua boca. Depois que a seda envolve seu corpo, ela endurece. Este Pokémon se prepara para a evolução dentro do casulo."},"269":{"genus":"Pokémon Mariposa Venenosa","text":"Dustox é atraído instintivamente pela luz. Enxames deste Pokémon são atraídos pelas luzes brilhantes das cidades, onde causam estragos ao arrancar as folhas das árvores à beira das ruas para se alimentar."},"270":{"genus":"Pokémon Erva Aquática","text":"Vive à procura de água limpa. Se ficar muito tempo sem beber água, a folha em sua cabeça murcha."},"271":{"genus":"Pokémon Alegre","text":"Vive à beira d'água, em lugares ensolarados. Durante o dia, dorme sobre uma cama de plantas aquáticas e fica ativo à noite."},"272":{"genus":"Pokémon Despreocupado","text":"Ludicolo começa a dançar assim que ouve uma música alegre e festiva. Dizem que este Pokémon aparece quando ouve crianças cantando durante passeios e trilhas."},"273":{"genus":"Pokémon Bolota","text":"Seedot se prende a um galho de árvore usando o topo da cabeça. Suga a umidade da árvore enquanto fica pendurado no galho. Quanto mais água bebe, mais brilhante fica o corpo deste Pokémon."},"274":{"genus":"Pokémon Astuto","text":"Nuzleaf vive em florestas densas e cheias de vegetação. De vez em quando, se aventura para fora da floresta para assustar as pessoas. Este Pokémon não gosta que apertem seu nariz comprido."},"275":{"genus":"Pokémon Perverso","text":"Vive em silêncio nas profundezas da floresta. Dizem que cria os ventos gelados do inverno com os leques que segura."},"276":{"genus":"Pokémon Andorinha Pequena","text":"Taillow enfrenta os inimigos com coragem, por mais fortes que sejam. Este Pokémon destemido continua desafiador mesmo depois de uma derrota. Por outro lado, chora alto quando fica com fome."},"277":{"genus":"Pokémon Andorinha","text":"Swellow voa bem acima de nossas cabeças, fazendo arcos graciosos no céu. Este Pokémon mergulha em um ângulo íngreme assim que avista uma presa. A presa infeliz é agarrada com força pelas garras de Swellow, sem chance de fuga."},"278":{"genus":"Pokémon Gaivota","text":"Wingull tem o hábito de carregar presas e objetos de valor no bico e escondê-los em todo tipo de lugar. Este Pokémon pega carona no vento e voa como se estivesse patinando pelo céu."},"279":{"genus":"Pokémon Ave Aquática","text":"É um mensageiro dos céus, que carrega pequenos Pokémon e ovos em segurança dentro do bico."},"280":{"genus":"Pokémon Sentimento","text":"Ralts sente as emoções das pessoas usando os chifres em sua cabeça. Este Pokémon raramente aparece diante das pessoas. Mas, quando aparece, se aproxima se sentir que a pessoa tem uma disposição positiva."},"281":{"genus":"Pokémon Emoção","text":"Dizem que um Kirlia exposto às emoções positivas de seu Treinador cresce lindo. Este Pokémon controla poderes psicocinéticos com seu cérebro altamente desenvolvido."},"282":{"genus":"Pokémon Abraço","text":"Gardevoir tem a habilidade de prever o futuro. Dizem que, se sentir que seu Treinador corre perigo iminente, este Pokémon libera sua energia psicocinética com força total."},"283":{"genus":"Pokémon Patinador","text":"Pelas pontas dos pés, Surskit secreta um óleo que permite que ande sobre a água como se estivesse patinando. Este Pokémon se alimenta de organismos microscópicos em lagoas e lagos."},"284":{"genus":"Pokémon Globo Ocular","text":"Masquerain intimida os inimigos com os padrões em forma de olho em suas antenas. Este Pokémon bate suas quatro asas para voar livremente em qualquer direção, até de lado e para trás, como se fosse um helicóptero."},"285":{"genus":"Pokémon Cogumelo","text":"Shroomish vive no solo úmido das partes escuras e profundas das florestas. Costuma ser encontrado imóvel embaixo de folhas caídas. Este Pokémon se alimenta de adubo feito de folhas caídas e apodrecidas."},"286":{"genus":"Pokémon Cogumelo","text":"Breloom se aproxima do inimigo com passos leves e ágeis e então desfere socos com seus braços elásticos. A técnica de luta deste Pokémon deixa os boxeadores no chinelo."},"287":{"genus":"Pokémon Folgado","text":"Slakoth fica largado por mais de vinte horas todos os dias. Como se move tão pouco, não precisa de muita comida. A única refeição diária deste Pokémon consiste em apenas três folhas."},"288":{"genus":"Pokémon Macaco Selvagem","text":"Vigoroth está sempre inquieto e louco para sair causando confusão. Simplesmente não suporta ficar parado nem por um minuto. O nível de estresse deste Pokémon aumenta se ele não puder se mexer o tempo todo."},"289":{"genus":"Pokémon Preguiçoso","text":"Slaking passa o dia inteiro deitado, sem fazer nada. Come a grama que cresce ao seu alcance. Se comer toda a grama que consegue alcançar, este Pokémon se muda de má vontade para outro lugar."},"290":{"genus":"Pokémon Aprendiz","text":"Nincada vive debaixo da terra por muitos anos, em completa escuridão. Este Pokémon absorve nutrientes das raízes das árvores. Fica imóvel enquanto espera a evolução."},"291":{"genus":"Pokémon Ninja","text":"Ninjask se move em velocidade tão alta que não pode ser visto, mesmo quando seu grito é ouvido com clareza. Por isso, por muito tempo acreditou-se que este Pokémon era invisível."},"292":{"genus":"Pokémon Muda","text":"O corpo duro de Shedinja não se mexe, nem um pouquinho. Na verdade, seu corpo parece ser apenas uma casca oca. Acredita-se que este Pokémon rouba a alma de quem espiar dentro de seu corpo oco pelas costas."},"293":{"genus":"Pokémon Sussurro","text":"Normalmente, a voz de Whismur é muito baixa, quase inaudível, mesmo prestando muita atenção. Porém, se este Pokémon sente perigo, começa a chorar em um volume ensurdecedor."},"294":{"genus":"Pokémon Vozeirão","text":"Os berros de Loudred conseguem destruir completamente uma casa de madeira. Ele usa a voz para punir os inimigos. As orelhas redondas deste Pokémon funcionam como alto-falantes."},"295":{"genus":"Pokémon Estrondo","text":"Exploud provoca terremotos com os tremores que cria ao berrar. Se este Pokémon inspira violentamente pelos orifícios de seu corpo, é sinal de que está se preparando para soltar um berro enorme."},"296":{"genus":"Pokémon Coragem","text":"Makuhita é persistente: continua se levantando e atacando o inimigo, não importa quantas vezes seja derrubado. Toda vez que se levanta, este Pokémon armazena mais energia no corpo para evoluir."},"297":{"genus":"Pokémon Empurrão","text":"Tem o hábito de desafiar os outros para testes de força sem hesitar. Já foi visto parado sobre trilhos de trem, parando trens com empurrões dos antebraços."},"298":{"genus":"Pokémon Bolinhas","text":"Um Pokémon que vive perto da água. Move-se rapidamente em terra quicando sobre sua cauda grande."},"299":{"genus":"Pokémon Bússola","text":"O nariz magnético de Nosepass está sempre apontado para o norte. Se dois destes Pokémon se encontram, não conseguem virar o rosto um para o outro quando estão perto, porque seus narizes magnéticos se repelem."},"300":{"genus":"Pokémon Gatinho","text":"Skitty tem o hábito de ficar fascinado por objetos em movimento e persegui-los. Este Pokémon é conhecido por correr atrás da própria cauda até ficar tonto."},"301":{"genus":"Pokémon Requintado","text":"Delcatty prefere levar uma vida sem amarras, em que pode fazer o que quiser no seu próprio ritmo. Como este Pokémon come e dorme quando bem entende, sua rotina diária é completamente aleatória."},"302":{"genus":"Pokémon Escuridão","text":"Sableye leva uma vida tranquila nas profundezas das cavernas. Mesmo assim, é temido, pois acredita-se que estes Pokémon roubam a alma das pessoas quando seus olhos ardem com um brilho sinistro na escuridão."},"303":{"genus":"Pokémon Enganador","text":"As enormes mandíbulas de Mawile são, na verdade, chifres de aço que se transformaram. Seu rosto de aparência dócil serve para fazer o inimigo baixar a guarda. Quando o inimigo menos espera, Mawile o abocanha com suas mandíbulas escancaradas."},"304":{"genus":"Pokémon Armadura de Ferro","text":"Este Pokémon tem um corpo de aço. Para formar seu corpo, Aron se alimenta do minério de ferro que escava das montanhas. De vez em quando, causa grandes problemas ao comer pontes e trilhos."},"305":{"genus":"Pokémon Armadura de Ferro","text":"Lairon fortalece seu corpo de aço bebendo água mineral de fonte, altamente nutritiva, até ficar estufado. Este Pokémon faz seu ninho perto de fontes de água deliciosa."},"306":{"genus":"Pokémon Armadura de Ferro","text":"Aggron reivindica uma montanha inteira como seu território. Espanca sem piedade qualquer coisa que viole seu ambiente. Este Pokémon patrulha seu território com vigilância o tempo todo."},"307":{"genus":"Pokémon Meditação","text":"Meditite passa por um treinamento mental rigoroso nas profundezas das montanhas. Porém, sempre que medita, este Pokémon perde a concentração e o foco. Por isso, seu treinamento nunca termina."},"308":{"genus":"Pokémon Meditação","text":"Dizem que, por meio da meditação, Medicham aumenta a energia dentro de seu corpo e aguça seu sexto sentido. Este Pokémon esconde sua presença fundindo-se com campos e montanhas."},"309":{"genus":"Pokémon Relâmpago","text":"Electrike armazena eletricidade em seus longos pelos. Este Pokémon estimula os músculos das pernas com cargas elétricas. Esses choques de energia dão às suas pernas uma aceleração explosiva."},"310":{"genus":"Pokémon Descarga","text":"Manectric está sempre descarregando eletricidade pela juba. As faíscas às vezes provocam incêndios florestais. Quando entra em uma batalha, este Pokémon cria nuvens de tempestade."},"311":{"genus":"Pokémon Torcida","text":"Plusle sempre age como líder de torcida de seus parceiros. Sempre que um colega de equipe se esforça bem em batalha, este Pokémon provoca um curto-circuito no corpo, criando estalos de faíscas para mostrar sua alegria."},"312":{"genus":"Pokémon Torcida","text":"Minun se preocupa mais em torcer pelos parceiros do que com a própria segurança. Provoca um curto-circuito na eletricidade de seu corpo para criar chuvas brilhantes de faíscas e animar seus colegas de equipe."},"313":{"genus":"Pokémon Vaga-lume","text":"Com a chegada da noite, Volbeat emite luz pela cauda. Comunica-se com os outros ajustando a intensidade e as piscadas de sua luz. Este Pokémon é atraído pelo aroma doce de Illumise."},"314":{"genus":"Pokémon Vaga-lume","text":"Com seu aroma doce, guia os Volbeat para desenharem símbolos com luz no céu noturno."},"315":{"genus":"Pokémon Espinho","text":"Roselia dispara espinhos afiados como projéteis contra qualquer oponente que tente roubar as flores de seus braços. O aroma deste Pokémon traz serenidade aos seres vivos."},"316":{"genus":"Pokémon Estômago","text":"Praticamente todo o corpo de Gulpin é seu estômago. Por isso, consegue engolir algo do seu próprio tamanho. O estômago deste Pokémon contém um fluido especial que digere qualquer coisa."},"317":{"genus":"Pokémon Bolsa de Veneno","text":"Quando Swalot avista uma presa, expele pelos poros um fluido terrivelmente tóxico e borrifa o alvo. Depois que a presa enfraquece, este Pokémon a engole inteira com sua boca enorme."},"318":{"genus":"Pokémon Selvagem","text":"As mandíbulas bem desenvolvidas e as presas pontiagudas de Carvanha têm poder destrutivo suficiente para arrancar o casco de barcos. Muitos barcos já foram atacados e afundados por este Pokémon."},"319":{"genus":"Pokémon Brutal","text":"Apelidado de \"o valentão dos mares\", Sharpedo é amplamente temido. Suas presas cruéis crescem de novo imediatamente se quebrarem. Um único destes Pokémon consegue despedaçar completamente um superpetroleiro."},"320":{"genus":"Pokémon Baleia-Bola","text":"As narinas de Wailmer ficam acima dos olhos. Este Pokémon brincalhão adora assustar as pessoas soltando com força, pelas narinas, a água do mar que armazena dentro do corpo."},"321":{"genus":"Pokémon Baleia Flutuante","text":"Wailord é o maior de todos os Pokémon identificados até hoje. Este Pokémon gigante nada preguiçosamente no vasto mar aberto, comendo enormes quantidades de comida de uma só vez com sua boca gigantesca."},"322":{"genus":"Pokémon Dormente","text":"Numel é extremamente lerdo: nem percebe quando é atingido. Porém, não suporta sentir fome nem por um segundo. O corpo deste Pokémon é um caldeirão fervente de magma."},"323":{"genus":"Pokémon Erupção","text":"Camerupt tem um vulcão dentro do corpo. Magma a cerca de 10.000 °C corre por seu corpo. De vez em quando, as corcovas nas costas deste Pokémon entram em erupção, expelindo o magma superaquecido."},"324":{"genus":"Pokémon Carvão","text":"Dá para saber como ele está se sentindo pela fumaça que sai de seu casco. Uma fumaça saindo com muita força é sinal de boa saúde."},"325":{"genus":"Pokémon Salto","text":"Spoink pula por aí apoiado na cauda. O impacto dos saltos faz seu coração bater. Por isso, este Pokémon não pode se dar ao luxo de parar de pular: se parar, seu coração para."},"326":{"genus":"Pokémon Manipulação","text":"Grumpig usa as pérolas pretas de seu corpo para amplificar suas ondas de poder psíquico e obter controle total sobre o inimigo. Quando este Pokémon usa seu poder especial, sua respiração fungada fica ofegante."},"327":{"genus":"Pokémon Panda Pintado","text":"Não existem dois Spinda com o mesmo padrão de manchas. Seu andar cambaleante atrapalha a mira dos inimigos."},"328":{"genus":"Pokémon Formiga-Leão","text":"O ninho de Trapinch é um buraco inclinado em forma de tigela, cavado na areia. Este Pokémon espera pacientemente que uma presa caia no buraco. Suas mandíbulas gigantes têm força suficiente para esmagar até rochas."},"329":{"genus":"Pokémon Vibração","text":"Para fazer as presas desmaiarem, Vibrava gera ondas ultrassônicas vibrando vigorosamente suas duas asas. As ondas ultrassônicas deste Pokémon são tão fortes que podem causar dores de cabeça nas pessoas."},"330":{"genus":"Pokémon Místico","text":"Flygon é apelidado de \"o espírito elemental do deserto\". Como o bater de suas asas levanta uma nuvem de areia, este Pokémon está sempre envolto em uma tempestade de areia enquanto voa."},"331":{"genus":"Pokémon Cacto","text":"Cacnea vive em locais áridos, como desertos. Libera um aroma forte de sua flor para atrair presas. Quando uma presa se aproxima, este Pokémon dispara espinhos afiados do corpo para derrubar a vítima."},"332":{"genus":"Pokémon Espantalho","text":"Durante o dia, Cacturne fica imóvel para não perder umidade sob o sol escaldante do deserto. Este Pokémon fica ativo à noite, quando a temperatura cai."},"333":{"genus":"Pokémon Pássaro de Algodão","text":"Swablu tem asas leves e fofas, que parecem nuvens de algodão. Este Pokémon não tem medo de pessoas. Pousa na cabeça delas e fica ali sentado como um chapéu de algodão."},"334":{"genus":"Pokémon Cantarolante","text":"Altaria dança e faz voltas no céu entre nuvens fofas que parecem algodão. Cantando melodias com sua voz cristalina, este Pokémon faz quem o ouve sentir um encantamento de sonho."},"335":{"genus":"Pokémon Gato-Furão","text":"As memórias das batalhas contra seu arqui-inimigo Seviper estão gravadas em cada célula do corpo de Zangoose. Este Pokémon desvia de ataques com destreza e uma agilidade incrível."},"336":{"genus":"Pokémon Cobra de Presas","text":"Seviper mantém uma rixa de gerações com Zangoose. As cicatrizes em seu corpo são prova de batalhas violentas. Este Pokémon ataca usando sua cauda afiada como uma espada."},"337":{"genus":"Pokémon Meteorito","text":"Lunatone foi descoberto em um local onde caiu um meteorito. Por isso, algumas pessoas acreditam que este Pokémon veio do espaço. Porém, até hoje ninguém conseguiu provar essa teoria."},"338":{"genus":"Pokémon Meteorito","text":"A energia solar é a fonte de seu poder, por isso ele é forte durante o dia. Quando gira, seu corpo brilha."},"339":{"genus":"Pokémon Bigodes","text":"Os bigodes sensíveis de Barboach funcionam como um excelente sistema de radar. Este Pokémon se esconde na lama, deixando apenas os dois bigodes expostos enquanto espera uma presa passar."},"340":{"genus":"Pokémon Bigodes","text":"Whiscash é extremamente territorialista. Um único destes Pokémon reivindica uma lagoa grande como seu território exclusivo. Se um inimigo se aproxima, ele se debate e provoca um terremoto gigantesco."},"341":{"genus":"Pokémon Arruaceiro","text":"Sua vitalidade resistente permite que se adapte a qualquer ambiente. Suas pinças nunca soltam uma presa."},"342":{"genus":"Pokémon Malandro","text":"Crawdaunt tem uma natureza extremamente violenta, que o leva a desafiar outros seres vivos para batalhas. Outras formas de vida se recusam a viver em lagoas habitadas por este Pokémon, tornando-as lugares desolados."},"343":{"genus":"Pokémon Boneco de Argila","text":"Baltoy se move girando sobre seu único pé. Pinturas rupestres primitivas que mostram este Pokémon vivendo entre as pessoas foram descobertas em algumas ruínas antigas."},"344":{"genus":"Pokémon Boneco de Argila","text":"Dizem que os Claydol são bonecos de barro feitos por humanos primitivos e que ganharam vida ao serem expostos a um raio misterioso. Este Pokémon se locomove levitando."},"345":{"genus":"Pokémon Lírio-do-Mar","text":"Lileep foi extinto há aproximadamente cem milhões de anos. Este Pokémon antigo se prende a uma rocha no fundo do mar e captura as presas que se aproximam usando tentáculos em forma de pétalas de flor."},"346":{"genus":"Pokémon Craca","text":"Cradily vagueia pelo fundo do oceano em busca de comida. Este Pokémon estica livremente seu pescoço, que parece um tronco de árvore, e captura presas desatentas com seus oito tentáculos."},"347":{"genus":"Pokémon Camarão Antigo","text":"Anorith foi regenerado a partir de um fóssil pré-histórico. Este Pokémon primitivo vivia em mares quentes. Ele agarra a presa com firmeza entre suas duas garras grandes."},"348":{"genus":"Pokémon Placa","text":"A armadura resistente de Armaldo faz todos os ataques ricochetearem. As duas garras enormes deste Pokémon podem ser estendidas ou recolhidas livremente. Elas têm força para atravessar uma placa de aço com um soco."},"349":{"genus":"Pokémon Peixe","text":"As barbatanas de Feebas são rasgadas e esfarrapadas desde o início de sua vida. Por causa de sua aparência malcuidada, este Pokémon é bastante ignorado. Consegue viver tanto no mar quanto em rios."},"350":{"genus":"Pokémon Ternura","text":"Suas escamas encantadoras são descritas como da cor do arco-íris. Elas mudam de cor dependendo do ângulo de visão."},"351":{"genus":"Pokémon Clima","text":"A aparência de Castform muda de acordo com o clima. Este Pokémon ganhou a habilidade de usar o vasto poder da natureza para proteger seu corpo minúsculo."},"352":{"genus":"Pokémon Troca de Cor","text":"Muda a cor do corpo para se camuflar no ambiente. Também muda de cor quando está feliz ou triste."},"353":{"genus":"Pokémon Fantoche","text":"Shuppet é atraído por sentimentos de inveja e rancor. Se alguém desenvolve um forte desejo de vingança, estes Pokémon aparecem em bando e se enfileiram sob o beiral da casa dessa pessoa."},"354":{"genus":"Pokémon Marionete","text":"Banette gera energia para lançar maldições poderosas espetando alfinetes no próprio corpo. Originalmente, este Pokémon era um boneco de pelúcia digno de pena que foi jogado fora."},"355":{"genus":"Pokémon Réquiem","text":"Duskull consegue atravessar qualquer parede, por mais grossa que seja. Depois que este Pokémon escolhe um alvo, persegue a vítima obstinadamente até o raiar do dia."},"356":{"genus":"Pokémon Aceno","text":"O corpo de Dusclops é completamente oco: não há absolutamente nada dentro. Dizem que seu corpo é como um buraco negro. Este Pokémon absorve qualquer coisa para dentro do corpo, mas nada jamais sai de volta."},"357":{"genus":"Pokémon Fruta","text":"Os cachos de frutas ao redor do pescoço de Tropius fazem muito sucesso entre as crianças. Este Pokémon adora frutas e come sem parar. Aparentemente, seu amor pelas frutas fez com que elas crescessem em seu próprio corpo."},"358":{"genus":"Pokémon Sino dos Ventos","text":"Chimecho faz seus gritos ecoarem dentro de seu corpo oco. Quando este Pokémon fica furioso, seus gritos se transformam em ondas ultrassônicas com força para arremessar os inimigos longe."},"359":{"genus":"Pokémon Desastre","text":"Toda vez que Absol aparece diante das pessoas, um desastre acontece logo depois, como um terremoto ou um maremoto. Por isso, passou a ser conhecido como o Pokémon do desastre."},"360":{"genus":"Pokémon Radiante","text":"Wynaut é sempre visto com um sorriso grande e feliz no rosto. Olhe para sua cauda para saber se ele está bravo. Quando fica bravo, este Pokémon bate a cauda no chão."},"361":{"genus":"Pokémon Gorro de Neve","text":"Snorunt vive em regiões com muita neve. Nas estações sem neve, como a primavera e o verão, este Pokémon se esconde para viver em silêncio entre estalactites e estalagmites nas profundezas das cavernas."},"362":{"genus":"Pokémon Rosto","text":"Glalie tem um corpo feito de rocha, que ele endurece com uma armadura de gelo. Este Pokémon tem a habilidade de congelar a umidade da atmosfera no formato que quiser."},"363":{"genus":"Pokémon Aplauso","text":"Spheal se locomove muito mais rápido rolando do que andando. Quando grupos destes Pokémon comem, todos batem palmas ao mesmo tempo para mostrar sua satisfação. Por isso, a hora das refeições deles é barulhenta."},"364":{"genus":"Pokémon Bola Rolante","text":"Sealeo tem o hábito de sempre equilibrar na ponta do nariz qualquer coisa que vê pela primeira vez. De vez em quando, este Pokémon se diverte equilibrando e girando um Spheal no nariz."},"365":{"genus":"Pokémon Quebra-Gelo","text":"Nada por mares gelados enquanto estilhaça blocos de gelo flutuantes com suas presas grandes. É protegido por sua grossa camada de gordura."},"366":{"genus":"Pokémon Bivalve","text":"A concha resistente de Clamperl não serve só para proteção: também é usada para prender e capturar presas. A concha de um Clamperl adulto fica coberta de entalhes e arranhões por toda parte."},"367":{"genus":"Pokémon Mar Profundo","text":"A existência de Huntail passou despercebida pelas pessoas por muito tempo, porque ele vive em profundezas extremas do mar. Os olhos deste Pokémon enxergam com clareza até nas profundezas escuras e turvas do oceano."},"368":{"genus":"Pokémon Mar do Sul","text":"Gorebyss vive nos mares do sul, em profundezas extremas. Seu corpo é feito para suportar a enorme pressão da água em profundidades incríveis. Por isso, o corpo deste Pokémon não sofre danos com ataques comuns."},"369":{"genus":"Pokémon Longevidade","text":"Relicanth é uma espécie de Pokémon que existe há cem milhões de anos sem nunca mudar de forma. Este Pokémon antigo se alimenta de organismos microscópicos com sua boca sem dentes."},"370":{"genus":"Pokémon Encontro","text":"Luvdisc vive em mares rasos dos trópicos. Este Pokémon em forma de coração ganhou seu nome por nadar atrás dos casais apaixonados que avistava entre as ondas do oceano."},"371":{"genus":"Pokémon Cabeça de Pedra","text":"Sonhando em um dia voar, pratica todos os dias saltando de penhascos."},"372":{"genus":"Pokémon Resistência","text":"Dentro da casca de Shelgon, que parece uma armadura, as células estão em plena transformação para criar um corpo totalmente novo. A casca deste Pokémon é extremamente pesada, o que deixa seus movimentos lentos."},"373":{"genus":"Pokémon Dragão","text":"Salamence surgiu como resultado de um sonho forte e antigo de ganhar asas. Dizem que esse desejo poderoso provocou uma mutação repentina nas células deste Pokémon, fazendo brotar suas asas magníficas."},"374":{"genus":"Pokémon Bola de Ferro","text":"Em vez de sangue, uma poderosa força magnética corre por todo o corpo de Beldum. Este Pokémon se comunica com os outros enviando pulsos magnéticos controlados."},"375":{"genus":"Pokémon Garra de Ferro","text":"Quando dois Beldum se fundem, forma-se um Metang. Os cérebros dos Beldum são ligados por um sistema nervoso magnético. Ao conectar seus cérebros magneticamente, este Pokémon gera um forte poder psicocinético."},"376":{"genus":"Pokémon Perna de Ferro","text":"Metagross tem quatro cérebros no total. Juntos, os quatro cérebros resolvem cálculos difíceis com facilidade e mais rápido que um supercomputador. Este Pokémon consegue flutuar no ar recolhendo suas quatro pernas."},"377":{"genus":"Pokémon Pico Rochoso","text":"Seu corpo inteiro é feito de rocha. Se alguma parte se lasca em batalha, ele gruda pedras no corpo para se consertar."},"378":{"genus":"Pokémon Iceberg","text":"O corpo de Regice foi formado durante uma era glacial. Esse corpo profundamente congelado não derrete nem com fogo. Este Pokémon controla um ar gélido de 200 °C negativos."},"379":{"genus":"Pokémon Ferro","text":"Registeel tem um corpo mais duro que qualquer tipo de metal. Aparentemente, seu corpo é oco. Ninguém faz ideia do que este Pokémon come."},"380":{"genus":"Pokémon Éon","text":"Latias é extremamente sensível às emoções das pessoas. Se sente qualquer hostilidade, este Pokémon eriça as penas de todo o corpo e solta gritos agudos para intimidar o inimigo."},"381":{"genus":"Pokémon Éon","text":"Latios tem a habilidade de fazer o inimigo ver uma imagem do que ele viu ou está imaginando. Este Pokémon é inteligente e entende a fala humana."},"382":{"genus":"Pokémon Bacia Marinha","text":"Kyogre tem o poder de criar enormes nuvens de chuva que cobrem o céu inteiro e trazem chuvas torrenciais. Este Pokémon salvou pessoas que sofriam com secas."},"383":{"genus":"Pokémon Continente","text":"Groudon é descrito há muito tempo na mitologia como o Pokémon que ergueu as terras e expandiu os continentes. Este Pokémon caiu no sono após uma batalha catastrófica contra Kyogre."},"384":{"genus":"Pokémon Céu Alto","text":"Rayquaza viveu por centenas de milhões de anos na camada de ozônio da Terra, sem nunca descer ao chão. Este Pokémon parece se alimentar de água e de partículas da atmosfera."},"385":{"genus":"Pokémon Desejo","text":"Uma lenda diz que Jirachi realiza qualquer desejo escrito nos bilhetes presos à sua cabeça quando ele desperta. Se este Pokémon sentir perigo, lutará sem acordar."},"386":{"genus":"Pokémon DNA","text":"O DNA de um vírus espacial sofreu uma mutação repentina ao ser exposto a um raio laser, dando origem a Deoxys. O órgão cristalino no peito deste Pokémon parece ser seu cérebro."}};
